from pathlib import Path
import sys,ast,json,hashlib,shutil,os
ROOT=Path(__file__).resolve().parent;REPO=ROOT.parents[2]
SUPPORT=ROOT/'campaigns/nas-support-excitation-audit-20261008-v1'
