NAME='additional-closeout-v1'
SOURCES=json.loads("{\"audit.py\":\"\\\"\\\"\\\"第28回：全サイクルの契約・封印・会計・外部保存を実読取で照合する。\\\"\\\"\\\"\\nfrom paths import *\\nfrom collections import Counter\\nimport os,sqlite3,subprocess,shutil,time\\ndef verify():\\n    contract=read(HERE/'execution-contract.json')\\n    assert digest(HERE/'registration.json')==contract['registration_sha256']\\n    for n,h in contract['source_hashes'].items():assert digest(HERE/n)==h,n\\n    for n,h in contract['input_hashes'].items():assert digest(REPO/n)==h,n\\n    return contract\\ndef main():\\n    contract=verify();b=Budget();b.recover();v=b.snapshot()\\n    assert len(v['campaigns'])==28 and not v['jobs']\\n    assert all(c['closed'] for n,c in v['campaigns'].items() if n!=NAME)\\n    cache={};hash_bytes=0\\n    def hashed(path):\\n        nonlocal hash_bytes\\n        physical=str(Path(path).resolve(strict=True))\\n        if physical not in cache:\\n            size=Path(physical).stat().st_size\\n            cache[physical]=dict(bytes=size,sha256=digest(physical))\\n            hash_bytes+=size\\n        return cache[physical]['sha256']\\n    with b.job(NAME,'audit','全27終了封印・52390移動・全外部・予算と一時を統合照合',reserve_bytes=80_000_000) as job:\\n        seals={};references=0\\n        for name,c in v['campaigns'].items():\\n            if name==NAME:continue\\n            p=ROOT/c['prefix']/'artifact-seal.json';seal=read(p)\\n            assert seal['path_base'] in ('repository',str(REPO))\\n            assert not seal.get('quality_goal_completed',False)\\n            for n,h in seal['files'].items():\\n                path=REPO/n\\n                assert not Path(n).is_absolute() and '..' not in Path(n).parts and path.is_file(),n\\n                assert hashed(path)==h,n\\n                references+=1\\n            seals[name]=dict(seal_sha256=digest(p),sealed_references_verified=len(seal['files']),\\n                experiment_completed=seal.get('experiment_completed',False),\\n                preparation_only=seal.get('preparation_only',False),quality_goal_completed=False,\\n                lifecycle=c,scientific_gate_unchanged=True)\\n            print('seal',name,len(seal['files']),flush=True)\\n        migration=REPO/'research/storage-migrations/2026-10-08-v1'\\n        plan=read(migration/'plan.json')\\n        for n,h in plan['sealed_documents'].items():assert hashed(REPO/n)==h,n\\n        db=migration/'manifest.sqlite'\\n        with sqlite3.connect('file:'+str(db)+'?mode=ro',uri=True) as con:\\n            rows=con.execute('SELECT name,physical,size,managed,status,sha256 FROM files ORDER BY name').fetchall()\\n        assert len(rows)==52390\\n        migrated_bytes=0;managed_count=0\\n        for i,(n,physical,size,managed,status,h) in enumerate(rows,1):\\n            logical=REPO/n;target=b.guard.root/physical\\n            assert status=='linked' and logical.is_symlink() and os.readlink(logical)==str(target),n\\n            assert target.is_file() and target.stat().st_size==size and hashed(target)==h,n\\n            migrated_bytes+=size;managed_count+=managed\\n            if i%5000==0:print('migration',i,len(rows),flush=True)\\n        assert migrated_bytes==21427485651\\n        locations=b.locations()\\n        for n,row in locations.items():\\n            target=b.guard.root/row['physical'];logical=ROOT/n\\n            assert logical.is_symlink() and os.readlink(logical)==str(target)\\n            assert target.stat().st_size==row['size'] and hashed(target)==row['sha256'],n\\n        frozen_inventory=b.reconcile();current=b.snapshot()\\n        running=current['jobs'];assert set(running)=={job}\\n        replay={};counts=Counter();failed=[];started=0;finished=0\\n        for line in (ROOT/'control/jobs.jsonl').read_text().splitlines():\\n            e=read_line(line)\\n            if e.get('event')=='start':\\n                assert e['id'] not in replay;replay[e['id']]=e\\n                counts[e['kind']]+=e['count'];started+=1\\n            elif e.get('event')=='finish':\\n                first=replay.pop(e['id']);assert first['campaign']==e['campaign'] and first['kind']==e['kind'] and first['count']==e['count']\\n                finished+=1\\n                if e['status']=='failed':failed.append(dict(id=e['id'],campaign=e['campaign'],kind=e['kind'],label=e['label'],error=e['error']))\\n        assert set(replay)==set(running) and dict(counts)==current['counts']\\n        total=Counter()\\n        for n,c in current['campaigns'].items():\\n            total.update(c['counts'])\\n            assert c['payload_bytes']<c['limits']['bytes']\\n            for k,used in c['counts'].items():assert used<=c['limits'][k],(n,k)\\n            duration=(current['seconds'] if not c['closed'] else c['end_seconds'])-c['start_seconds']\\n            assert duration<c['limits']['seconds'],(n,duration)\\n        assert dict(total)==current['counts']\\n        for k,used in current['counts'].items():\\n            if k in current['limits']:assert used<=current['limits'][k],k\\n        assert current['seconds']<current['limits']['seconds']-14400\\n        assert current['write_bytes']<current['limits']['write_bytes']\\n        works=current.get('temporary_work',{})\\n        assert all(w['status']=='removed' and w['absence_verified'] and not os.path.lexists(w['path']) for w in works.values())\\n        workbase=b.guard.root/'work'/b.storage['cycle_directory']\\n        assert not workbase.exists() or not list(workbase.iterdir())\\n        assert not (ROOT/'control/state.tmp').exists()\\n        config=read(ROOT/'control/storage-config.json');b.guard.check()\\n        free_internal=shutil.disk_usage(ROOT).free;free_external=shutil.disk_usage(b.guard.mount).free\\n        assert free_internal>=20_000_000_000 and free_external>=config['external_closing_bytes']+80_000_000\\n        ext_bytes=sum(row['size'] for row in locations.values())\\n        aliases=sum(row['alias_size'] for row in locations.values())\\n        overhead=sum(p.stat().st_size for p in (ROOT/'control').iterdir() if p.is_file())\\n        internal=current['payload_bytes']-ext_bytes+aliases+overhead\\n        assert internal<config['internal_experiment_bytes'] and ext_bytes<config['external_experiment_bytes']\\n        cross=read(PREVIOUS/'aggregate-summary.json');period=read(PERIOD/'aggregate-summary.json');scope=read(PERIOD/'scope-denominator-audit.json')\\n        assert cross['old_group_counts_exact_match'] and cross['total_wave_records']==992 and cross['total_existing_ASR_records']==1984\\n        assert all(not m['old_qualification'] for c in cross['cohorts'].values() for m in c['methods'].values())\\n        assert not current['continuation_checkpoint'].get('protected_confirmation_opened',False)\\n        b.write_data(HERE/'integrity-manifest.json',encode(dict(physical_file_hashes=cache,\\n            bytes_read_once=hash_bytes,hash_only_no_signal_decoding=True,\\n            protected_evaluation_text_not_used=True)),job)\\n        result=dict(prior_campaigns=seals,prior_sealed_references=references,\\n            distinct_physical_files_hashed=len(cache),distinct_bytes_hashed=hash_bytes,\\n            current_external_files_verified=len(locations),current_external_bytes=ext_bytes,\\n            moved_files_verified=len(rows),moved_bytes=migrated_bytes,moved_managed_files=managed_count,\\n            preexisting_seal_documents_verified=len(plan['sealed_documents']),\\n            hash_cache_avoided_duplicate_read=True,old_scientific_contracts_and_gates_unchanged=True,\\n            all_jobs_replay_exact=True,job_starts=started,job_finishes=finished,current_audit_job_only=True,\\n            global_and_campaign_counts_exact=True,failed_jobs_preserved=failed,\\n            temporary_owned_workspaces=len(works),all_temporary_removed=True,\\n            temporary_paths_physically_absent=True,no_unregistered_work_children=True,new_temporary_files=0,\\n            volume_UUID=config['volume_uuid'],marker_sha256=config['marker_sha256'],volume_guard_passed=True,\\n            real_free_internal=free_internal,real_free_external=free_external,\\n            internal_arc_bytes_including_aliases_control=internal,\\n            whole_external_usage_not_inferred_from_arc_only=True,\\n            heldout_evaluation_not_opened=True,protected_confirmation_opened=False,\\n            cross_factor_summary_sha256=digest(PREVIOUS/'aggregate-summary.json'),\\n            source_period_summary_sha256=digest(PERIOD/'aggregate-summary.json'),\\n            source_period_scope=scope,new_scientific_outputs=0,\\n            final_runtime_independence_not_retested=True,previous_runtime_evidence_preserved=True,\\n            quality_goal_completed=False,perceptual_qualification=False,\\n            stop_reason='campaigns_limit_reached',campaigns_used=28,campaigns_limit=28,\\n            remaining_other_limits_not_reusable_as_campaigns=True,\\n            budget_at_audit=current,integrity_manifest_sha256=digest(HERE/'integrity-manifest.json'))\\n        # 大きな稼働台帳は集計に埋め込まず、明示した観測断面の容量・回数だけを残す。\\n        result['budget_at_audit']=dict(seconds=current['seconds'],counts=current['counts'],\\n            payload_bytes=current['payload_bytes'],write_bytes=current['write_bytes'],limits=current['limits'])\\n        b.save(HERE/'aggregate-summary.json',result,job)\\n        b.save(HERE/'file-integrity-audit.json',dict(unique_files=len(cache),unique_bytes=hash_bytes,\\n            seal_references=references,current_external_files=len(locations),migrated_files=len(rows),\\n            all_expected_hashes_matched=True,read_only_no_copy_or_regeneration=True,\\n            protected_text_semantically_unopened=True),job)\\n    print('audit complete',b.reconcile(),flush=True)\\ndef read_line(line):\\n    import json\\n    return json.loads(line)\\nif __name__=='__main__':main()\\n\",\"paths.py\":\"\\\"\\\"\\\"追加4枠の結果統合と包括終了監査。\\\"\\\"\\\"\\nfrom pathlib import Path\\nimport sys\\nHERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];REPO=ROOT.parents[2]\\nsys.path.insert(0,str(ROOT))\\nfrom budget import read,digest,encode\\nfrom temporary_storage import ManagedStorageBudget as Budget\\nNAME='additional-closeout-v1'\\nPREVIOUS=ROOT/'campaigns/nas-cross-factor-failure-audit-20261008-v1'\\nPERIOD=ROOT/'campaigns/nas-source-period-audit-20261008-v1'\\nWINDOW=ROOT/'campaigns/nas-hts-window-audit-20261008-v1'\\nWORLD=ROOT/'campaigns/nas-world-excitation-audit-20261008-v1'\\nSUPPORT=ROOT/'campaigns/nas-support-excitation-audit-20261008-v1'\\n\",\"integrate.py\":\"\\\"\\\"\\\"全結果と二ASR悪化群から次の制御比較の有効性を判断する。\\\"\\\"\\\"\\nfrom paths import *\\nfrom collections import Counter\\ndef main():\\n    from audit import verify\\n    verify();b=Budget();b.recover()\\n    with b.job(NAME,'audit','既存992/1984ASR・追加測定/源区分・次の比較条件を統合',reserve_bytes=3000000) as j:\\n        cross=read(PREVIOUS/'aggregate-summary.json');window=read(WINDOW/'aggregate-summary.json');world=read(WORLD/'aggregate-summary.json');support=read(SUPPORT/'aggregate-summary.json')\\n        assert cross['total_wave_records']==support['total']==992 and cross['total_existing_ASR_records']==1984\\n        assert support['actual_HTS_source_known']==224 and support['WORLD_actual_source_unknown']==768\\n        assert world['full_corpus_observations']==0 and not world['observer_qualified']\\n        methods={};all_source=Counter();missing_source=Counter()\\n        for cohort,c in cross['cohorts'].items():\\n            for method,m in c['methods'].items():\\n                key=cohort.removesuffix('-20261008-v1')+'/'+method;s=support['groups'][key]\\n                assert s['files']==m['expected']==32 and not m['old_qualification']\\n                all_source.update(s['all_source_states']);missing_source.update(s['missing_source_states'])\\n                methods[key]=dict(files=32,pitch_pass=m['pitch_pass_count'],support_pass=m['support_pass_count'],\\n                    fixed_support_intervals=s['fixed_support_intervals'],missing_support_intervals=s['missing_intervals'],\\n                    source_known_files=s['known_source_files'],missing_source_states=s['missing_source_states'],\\n                    missing_drive_states=s['missing_drive_states'],old_qualification=m['old_qualification'],\\n                    content={engine:dict(groups=v['groups'],worsening_groups=v['worsening_groups'],\\n                        edit_operations=v['edit_operations'],old_groups_exact_match=v['old_groups_exact_match'])\\n                        for engine,v in m['content'].items()},\\n                    within_cohort_pairs_only=True,ASR_edits_not_aligned_to_source_intervals=True,diagnostic_not_causal=True)\\n        assert len(methods)==31\\n        summary=dict(methods=methods,known_HTS_wave_cases=224,unknown_WORLD_wave_cases=768,all_fixed_support_source_states=dict(all_source),\\n            missing_fixed_support_source_states=dict(missing_source),total_fixed_support_intervals=sum(x['fixed_support_intervals'] for x in methods.values()),\\n            missing_fixed_support_intervals=sum(x['missing_support_intervals'] for x in methods.values()),\\n            HTS_window_results=window['results'],WORLD_compatibility=world,\\n            source_pulse_presence_does_not_qualify_acoustic_or_perceived_pitch=True,\\n            next_new_control_comparison_valid_now=False,\\n            decision='未確認WORLDと短窓/動的測定の不足が残り、源不足と音響測定の失敗を十分に分離できない。次の係数比較を旧DIO/ACFだけで採否決定する根拠は不足。測定・源成分検証を先に進める。',\\n            required_before_control_comparison=['HTSでLPF後の周期寄与と音響測定の関係を旧波形不変で確認','WORLDで未観測原実装の再現差を演算段階へ分離し、純観測の全旧波形一致を得る','短区間・動的区間の測定可能な範囲と欠測を事前固定','新入力・同コホート対照・二ASR33群・旧内容保護・通常隔離/CLI証拠を新比較前に登録'],\\n            human_response_not_required_for_measurement_or_control_research=True,\\n            previous_content_protection_and_qualification_unchanged=True,new_ASR_or_waveform=0,\\n            quality_goal_completed=False,protected_confirmation_opened=False,perceptual_qualification=False)\\n        b.save(HERE/'integration-summary.json',summary,j)\\n        lines=['# 追加4枠の測定・励振・内容保護の統合','',\\n            '第25〜27回の結果と、6コホート31方式・992既存波形・1,984既存ASR記録の二認識器33群を統合した。全方式の旧資格は不通過のまま。コホート内のnative対照を保持し、コホート間の総率で順位を作らない。','',\\n            '現時点で、新たな係数比較の採否を旧DIO/ACFだけで判断する根拠は不足している。HTSの源時計は224件確認できたが、LPF後の周期寄与・知覚pitchは未確認。WORLD768件の実励振は互換不通過のためunknown。短窓・動的区間へ安定60ms資格を流用できない。','',\\n            '|コホート/方式|ピッチ通過/32|支持欠測区間|悪化群W/R|','|---|---:|---:|---|']\\n        for k,m in methods.items():lines.append(f\\\"|{k}|{m['pitch_pass']}|{m['missing_support_intervals']}|{len(m['content']['whisper']['worsening_groups'])}/{len(m['content']['reazon']['worsening_groups'])}|\\\")\\n        lines+=['',f\\\"固定支持は計{summary['total_fixed_support_intervals']}区間、欠測は{summary['missing_fixed_support_intervals']}区間。欠測の源区分: {dict(missing_source)}。\\\",\\n            '源の無声/短いパルス列と、パルス存在下の音響的な曖昧さを分けた。後者には周期成分の弱さ、SNR、残響、非定常、測定器の限界が混在し、測定器の失敗と断定しない。WORLDは未確認を保持した。kana編集は音素時刻と対応付けない。',\\n            '次は既存HTSのLPF後周期成分、WORLDの未観測原実装の演算再現、短窓/動的測定の対象範囲を検証する。新しい人の回答をこれらの研究の必須条件にしない。知覚資格・独立P5は未充足で、全体品質は未達。','']\\n        b.write(HERE/'integration-report.md','\\\\n'.join(lines).encode(),j)\\n    print(b.reconcile(),flush=True)\\nif __name__=='__main__':main()\\n\",\"closeout.py\":\"\\\"\\\"\\\"追加承認の28回を終了し、品質未達・再開条件を追記版へ保存する。\\\"\\\"\\\"\\nfrom paths import *\\ndef main():\\n    from audit import verify\\n    verify();b=Budget();b.recover();assert not b.snapshot()['jobs']\\n    with b.job(NAME,'audit','追加4枠の結果と包括監査を封印',reserve_bytes=5000000) as j:\\n        integrity=read(HERE/'aggregate-summary.json');integrated=read(HERE/'integration-summary.json')\\n        assert integrity['campaigns_used']==28 and not integrated['quality_goal_completed']\\n        c=b.snapshot()['campaigns'][NAME]\\n        b.save(HERE/'cost-audit.json',dict(campaign=c,render=0,DSP=0,AI=0,download=0,new_temp_files=0,\\n            all_temporary_removed=True,quality_goal_completed=False),j)\\n        files={str(p.relative_to(REPO)):digest(p) for p in HERE.rglob('*') if p.is_file()}\\n        b.save(HERE/'artifact-seal.json',dict(files=files,path_base='repository',experiment_completed=True,\\n            quality_goal_completed=False,protected_confirmation_opened=False),j)\\n        b.save(HERE/'completion-audit.json',dict(files_verified=len(files),seal_sha256=digest(HERE/'artifact-seal.json'),\\n            all_temporary_removed=True,quality_goal_completed=False),j)\\n    b.close_campaign(NAME);s=b.snapshot();assert len(s['campaigns'])==s['limits']['campaigns']==28\\n    assert all(c['closed'] for c in s['campaigns'].values()) and not s['jobs']\\n    remaining=dict(seconds=s['limits']['seconds']-s['seconds'],counts={k:s['limits'][k]-s['counts'].get(k,0) for k in ['render','teacher','ai','dsp','train','inverse','download']},\\n        campaigns=0,write_bytes=s['limits']['write_bytes']-s['write_bytes'])\\n    result=dict(cycle=s['cycle'],quality_goal_completed=False,protected_confirmation_opened=False,all28campaignsclosed=True,\\n        stop_reason='campaigns_limit_reached',campaigns_used=28,campaigns_limit=28,remaining=remaining,\\n        known_HTS_source_cases=224,unknown_WORLD_source_cases=768,\\n        fixed_support_intervals=integrated['total_fixed_support_intervals'],missing_fixed_support_intervals=integrated['missing_fixed_support_intervals'],\\n        missing_source_states=integrated['missing_fixed_support_source_states'],\\n        next_control_comparison_valid_now=False,integration=str((HERE/'integration-summary.json').relative_to(REPO)),\\n        comprehensive_audit=str((HERE/'aggregate-summary.json').relative_to(REPO)),audit_seal_sha256=digest(HERE/'artifact-seal.json'),\\n        final_quality_unmet=['新文全件の指定F0/固定有声支持','二ASR33群の内容保護','日本語非ニューラル音声に有効な知覚資格','独立P5最終確認'],\\n        no_new_human_answers_required_for_measurement_or_control_research=True,\\n        new_allocation_request='next-campaign-allocation-request-20261008-0002.md',\\n        budget=b.reconcile(),git_save_pending=True)\\n    b.save(ROOT/'progress-0041.json',result);b.save(ROOT/'cycle-closeout-result-20261008-0002.json',result)\\n    report=['# 追加4枠の終了結果（品質未達）','',\\n        '承認されたcampaign上限28回に到達したため、新しい科学campaignを停止する。時間・回数の残額をcampaign追加へ読み替えない。品質未達、P5未開封。',\\n        '第25回はHTS128件の短窓/動的測定を検証。中心ACFの安定60msは128/128、動的60msは25/128、20msは全件不通過。資格の対象範囲を保持した。',\\n        '第26回はWORLD768件を登録したが、観測Cの旧WAV完全一致が初回と技術再試行2回で不通過。最初の例のfloat32差は1サンプルの2.7756e-17だったが条件を緩和せず、全件観測を実行しなかった。旧PyWORLD再構成4例は完全一致。未確認768件を保持した。',\\n        '第27回はHTS追加96件を旧WAV完全一致で観測し、既存128件と合わせ224件の源周期/パルスを確認。全992件の固定支持・旧DIO・欠測件数は一致した。']\\n    report+=[f\\\"固定支持は{result['fixed_support_intervals']:,}区間、欠測{result['missing_fixed_support_intervals']:,}区間。源区分: {result['missing_source_states']}。\\\",\\n        '第28回は二ASR33群の旧不採択/悪化群と測定結果を統合。次の係数比較を旧測定だけで採否判断する根拠は不足。周期成分・短窓/動的測定・WORLD再現差の検証を先に行う必要がある。',\\n        f\\\"包括監査では終了済み27封印の{integrity['prior_sealed_references']:,}参照、外部登録{integrity['current_external_files_verified']:,}ファイル、移動52,390ファイルを照合。重複を除く{integrity['distinct_physical_files_hashed']:,}実体のSHA-256が一致。所有一時領域{integrity['temporary_owned_workspaces']}件は全件削除/物理不存在が一致した。\\\",\\n        '新しいASR・教師・学習・逆推定・制御比較は追加4枠で0。旧科学契約/封印/採否は上書きしていない。Gitは生データ/位置索引のバックアップを代替しない。','',\\n        '|項目|消費|上限|','|---|---:|---:|']\\n    for k in ['render','teacher','ai','dsp','train','inverse','download']:report.append(f\\\"|{k}|{s['counts'].get(k,0):,}|{s['limits'][k]:,}|\\\")\\n    report+=['',f\\\"監査時の稼働{s['seconds']/3600:.3f}時間、残り{remaining['seconds']/3600:.3f}時間（終了専用4時間を含む）。この後のGit/終端管理費を含む最新control/state.jsonを正本とする。\\\",\\n        '再開には追加配分案の承認が必要。旧24→28承認は保持し、新しい28→32案は未承認として保存した。次の制御比較やP5の開封はその案に含めない。',\\n        '終端Git保存では結果commitを記録し、自己参照commit記録の連鎖を避ける。終端commitのHEADとorigin/mainの実照合を行う。','']\\n    b.write(ROOT/'cycle-closeout-report-20261008-0002.md','\\\\n'.join(report).encode())\\n    proposal='''# 次の測定検証4枠の追加配分案（未承認）\\n\\n28回の承認枠が終了した。品質未達、WORLD768件の実励振は未確認、HTSの源パルス存在だけでは周期音響成分・短窓/動的測定・知覚pitchを保証できない。新しい係数比較へ進む根拠はまだ不足している。\\n\\n同じarc-20261004-v1でcampaign上限だけ28→32（最大4回）へ追補する案を提案する。既消費・48h・生成20,000・AI50,000・DSP100,000・teacher1,000・fit60・inverse300・取得5GB・金銭0・保存/書込上限を維持する。旧承認と封印は上書きしない。これは未承認で、承認されるまで開始しない。\\n\\n1. HTS224既存波形のLPF後の周期成分を純観測し、波形全件bytehash不変を条件に、源パルスと音響成分の関係を分離する。残響・雑音・動的区間を保持し、知覚資格へ広げない。\\n2. WORLDはobserver条件の単純な再反復をしない。観測を入れない原実装の再ビルドを旧PyWORLDと比べ、差の発生段階を演算単位へ分離する。旧波形不変を得る前に実励振truthを使わない。係数や許容差の調整はしない。\\n3. 既存波形・有効な実励振を使い、短い有声/動的区間の測定可否を検証する。新しい測定法や境界処理は出力前に登録し、不足対象・欠測を全分母に残す。旧DIO/ACFゲートや採否は変更しない。\\n4. 上記と二ASRの悪化群を統合し、制御比較へ進むための対象範囲・必要証拠を判断する。包括保存/会計/終了監査を行う。\\n\\n各回は通常4h・2GB以内、4回計最大16hを開始前に残時間と照合し、最後4hと両媒体2GBは保持する。事前の配分目安は生成計4,000、DSP24,000、依存取得最大1MB、AI/teacher/fit/inverse0。未使用回は使うことを目的に開始しない。各回の実入力・具体的処理・再試行・後始末を開始前に登録し、開始後に上限を増やさない。技術再試行は1ジョブ2回・campaign10回。RAM8GB、計算同時最大2を維持する。\\n\\n新しい合成経路、制御比較、P5開封、知覚ゲート緩和はこの案に含めない。新しい人の回答を測定・制御研究の必須条件にしない。品質達成は有効な知覚資格と独立P5を別途満たすまで認定しない。\\n\\n承認後は最新terminal-state、台帳、全封印、Git先端、指定媒体UUID/marker/空き、所有一時物不存在を照合して追補を新しい記録で適用する。第29回は結果に即した具体的契約の登録から始める。\\n'''\\n    b.write(ROOT/'next-campaign-allocation-request-20261008-0002.md',proposal.encode())\\n    with b.locked():\\n        s=b._load();s.setdefault('continuation_checkpoint_history',[]).append(s['continuation_checkpoint'])\\n        s['continuation_checkpoint']=dict(id='campaign-limit-stop-20261008-0002',active_campaign=None,all_campaigns_closed=True,\\n            stop_reason='campaigns_limit_reached',campaigns_used=28,campaigns_limit=28,quality_goal_completed=False,\\n            protected_confirmation_opened=False,all_temporary_removed=True,jobs={},approval_required_for_additional_campaigns=True,\\n            next='commit/push終了結果→終端台帳suspend/commit/push→28→32案の承認待ち',git_save_pending=True);b._write_state(s)\\n    print(b.reconcile(),flush=True)\\nif __name__=='__main__':main()\\n\"}")
def main():
    b=Budget();b.recover();v=b.snapshot()
    assert not v['jobs'] and len(v['campaigns'])==27 and all(c['closed'] for c in v['campaigns'].values())
    assert v['limits']['campaigns']==28 and v['limits']['seconds']-v['seconds']-14400>14400
    assert shutil.disk_usage(ROOT).free>=20000000000 and shutil.disk_usage(b.guard.root).free>=2500000000
    SOURCES['temporary_storage.py']=(SUPPORT/'temporary_storage.py').read_text().replace("owner = 'support-excitation-audit-'","owner = 'additional-closeout-'")
    for n,x in SOURCES.items():ast.parse(x,filename=n)
    reg=dict(campaign=NAME,status='registered_before_audit',purpose='追加4枠の結果/既存二ASR悪化群を統合し、次の制御比較が有効か判断。全保存/費用/終了を照合。',
        operations=['全27旧封印全参照とhash照合','全52390移動/全外部登録の実読取hash照合','全ジョブ/包括とcampaign費用の一致','全一時物削除/物理不存在/媒体UUID/marker/実空き',
            '全992固定支持・HTS224既知/WORLD768未知・短窓/動的測定の適用範囲','二ASRの旧33群と悪化群・不採択をコホート内で統合','新制御比較の有効性と必要証拠を判断','28回上限停止と品質未達を区別'],
        limits=dict(seconds=14400,bytes=250000000,render=0,dsp=0,ai=0,teacher=0,train=0,inverse=0,download=0,setup=40,audit=60),
        estimates=dict(integrity_manifest=50000000,metadata=10000000,retry_storage=150000000,peak_total=210000000),
        technical_retry_per_job=2,technical_retry_campaign=10,new_temp_required=False,stdlib_hash_only=True,
        no_copy_or_regeneration=True,new_signal_decoding_tracker_AI=0,old_gates_and_qualification_unchanged=True,
        protected_evaluation_text_not_used=True,final_runtime_independence_not_retested=True,
        quality_goal_completed=False,stop_reason='campaigns_limit_reached',budget_review='28/28。新経路/制御比較は加えず統合/終了。',
        previous_seal_sha256=digest(SUPPORT/'artifact-seal.json'))
    inputs={str((ROOT/c['prefix']/'artifact-seal.json').relative_to(REPO)):digest(ROOT/c['prefix']/'artifact-seal.json') for c in v['campaigns'].values()}
    for n in ['plan.json','manifest.sqlite','result.json','seal-content-audit.json']:
        p=REPO/'research/storage-migrations/2026-10-08-v1'/n;inputs[str(p.relative_to(REPO))]=digest(p)
    for n in ['docs/plans/neural-assisted-non-neural-speech-plan-2026-10-08.md','docs/plans/autonomous-research-budget-proposal-2026-10-04.md','docs/plans/autonomous-research-external-storage-amendment-2026-10-06.md','docs/plans/repository-data-storage-amendment-2026-10-08.md']:
        inputs[n]=digest(REPO/n)
    for n in ['campaign-allocation-approval-20261008-0001.json','additional-campaign-revalidation-20261008-0001.json','terminal-state-20261008-0001.json']:
        inputs[str((ROOT/n).relative_to(REPO))]=digest(ROOT/n)
    b.reconcile();b.start_campaign(NAME,str(HERE.relative_to(ROOT)),reg['limits'],hashlib.sha256(encode(reg)).hexdigest())
    with b.job(NAME,'setup','全27封印・追加承認・統合判断・包括監査を固定',reserve_bytes=300000) as j:
        b.save(HERE/'registration.json',reg,j)
        for n,x in SOURCES.items():b.write(HERE/n,x.encode(),j)
        b.save(HERE/'execution-contract.json',dict(registration_sha256=digest(HERE/'registration.json'),source_hashes={n:digest(HERE/n) for n in SOURCES},
            input_hashes=inputs,quality_goal_completed=False,protected_confirmation_opened=False),j)
        b.save(HERE/'preparation-audit.json',dict(AST_pass=True,all27priorclosed=True,old_seals_unchanged=True,new_temp0=True),j)
    addition='\n# 追加4枠の包括終了監査の実体hash詳細を外部保存。契約/集計/封印を追跡。\nresearch/experiments/autonomous-research-cycle/campaigns/nas-additional-closeout-20261008-v1/integrity-manifest.json\n'
    ignore=REPO/'.gitignore';assert addition not in ignore.read_text()
    with b.locked():
        s=b._load();s['write_bytes']+=len((ignore.read_text()+addition).encode());b.event(s,dict(kind='repository-small-metadata-write',path='.gitignore',charged_bytes=len((ignore.read_text()+addition).encode())))
        s.setdefault('continuation_checkpoint_history',[]).append(s['continuation_checkpoint'])
        s['continuation_checkpoint']=dict(id='additional-closeout-prepared-20261008-0001',active_campaign=NAME,campaign_closed=False,
            next='commit/push→audit.py→integrate.py→closeout.py→終端suspend/commit/push',git_save_pending=True,
            quality_goal_completed=False,protected_confirmation_opened=False);b._write_state(s)
    with ignore.open('a') as f:f.write(addition);f.flush();os.fsync(f.fileno())
    b.save(ROOT/'progress-0040.json',dict(active_campaign=NAME,all27priorclosed=True,new_wave_DSP_AI=0,quality_goal_completed=False,
        next='登録commit/push後に全封印/媒体/会計監査',budget=b.reconcile()))
    print(b.reconcile(),flush=True)
if __name__=='__main__':main()
